// Normalizes incoming rows from either Webhook (CSV/JSON) or Google Sheets
const rawItems = $input.all();
const normalizedProducts = [];

for (const item of rawItems) {
  const row = item.json.body || item.json;
  const title = (row.Title || row.title || row.Name || row.name || row['Product Name'] || '').toString().trim();
  if (!title) continue; // Skip header or empty rows

  let sku = (row.SKU || row.sku || row['Item Code'] || row.item_code || '').toString().trim();
  if (!sku) {
    sku = 'SKU-' + title.slice(0, 3).toUpperCase() + '-' + Math.floor(1000 + Math.random() * 9000);
  }

  const cleanPrice = (val) => {
    if (val === undefined || val === null || val === '') return 0;
    const cleaned = val.toString().replace(/[৳$BDT,\s]/gi, '').trim();
    const parsed = parseFloat(cleaned);
    return isNaN(parsed) ? 0 : parsed;
  };

  const basePrice = cleanPrice(row.Price || row.price || row['Base Price'] || row.base_price || row.MRP);
  const compareAtPrice = cleanPrice(row.ComparePrice || row.compare_at_price || row['Compare At Price']);
  const costPrice = cleanPrice(row.CostPrice || row.cost_price || row['Cost Price']);
  const stock = parseInt((row.Stock || row.stock || row['Initial Stock'] || 0).toString().replace(/[^0-9]/g, ''), 10) || 0;
  const category = (row.Category || row.category || row.Collection || '').toString().trim();
  const brand = (row.Brand || row.brand || '').toString().trim();
  const description = (row.Description || row.description || row.Details || '').toString().trim();
  const rawImages = (row.Images || row.images || row['Image URLs'] || '').toString().trim();

  const images = rawImages
    ? rawImages.split(/[,;\n]/).map(u => u.trim()).filter(u => u.startsWith('http://') || u.startsWith('https://'))
    : [];

  normalizedProducts.push({
    title,
    sku,
    base_price: basePrice,
    compare_at_price: compareAtPrice > 0 ? compareAtPrice : undefined,
    cost_price: costPrice > 0 ? costPrice : undefined,
    stock,
    category: category || undefined,
    brand: brand || undefined,
    description,
    images,
    status: (row.Status || row.status || 'ACTIVE').toString().toUpperCase()
  });
}

return [{
  json: {
    batch_id: 'n8n_batch_' + Date.now(),
    total_count: normalizedProducts.length,
    products: normalizedProducts
  }
}];

// Aggregate results across batches and prepare operator alert
const response = $input.first().json;
const data = response.data || response;

return [{
  json: {
    status: 'COMPLETE',
    batch_id: data.batch_id,
    total_processed: data.total_rows || 0,
    imported_count: data.imported_count || 0,
    updated_count: data.updated_count || 0,
    failed_count: data.failed_count || 0,
    created_categories: data.created_categories || [],
    error_samples: (data.errors || []).slice(0, 5),
    timestamp: new Date().toISOString()
  }
}];
